docker exec startuphafen-devcontainer-maildev-1 node -e '
const net=require("net");
const s=net.connect(1025,"127.0.0.1");
s.on("data",d=>process.stdout.write("S: "+d.toString()));
let phase="greeting", sent=0;
const dataLines=["From: noreply@startuphafen.de","To: user@example.com","Subject: validation-test","Content-Type: text/plain","","This is a maildev validation email.","","."];
s.on("data",d=>{
  const t=d.toString();
  if(phase==="greeting"){ s.write("EHLO validator\r\n"); phase="ehlo"; return; }
  if(phase==="ehlo"){ s.write("MAIL FROM:<test@startuphafen.de>\r\n"); phase="mail"; return; }
  if(phase==="mail"){ s.write("RCPT TO:<user@example.com>\r\n"); phase="rcpt"; return; }
  if(phase==="rcpt"){ if(/250 /.test(t)){ s.write("DATA\r\n"); phase="data"; } return; }
  if(phase==="data"){
    const c=t.trim();
    if(c.startsWith("250")){ console.log("\n=== MESSAGE ACCEPTED ==="); s.write("QUIT\r\n"); phase="quit"; }
  }
  if(phase==="quit" && /221/.test(t)){ console.log("=== QUIT OK ==="); s.end(); }
});
s.on("end",()=>process.exit(0));
setInterval(()=>{ if(phase==="data" && sent<dataLines.length){ s.write(dataLines[sent]+"\r\n"); sent++; } },400);
setTimeout(()=>{ console.log("TIMEOUT phase",phase,"sent",sent); process.exit(1); },9000);
' 2>&1

